import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, writeFileSync } from "node:fs";

// Derives each catalogued component's creation date from git history and
// writes src/storybook/componentTimeline.ts. Component identity comes from
// src/storybook/componentCatalog.ts: every entry's componentPath (a folder or
// a single file) is looked up in git for the commit that first added it. Only
// the git-derived facts live in the output — name, category and storyTitle
// stay owned by componentCatalog.ts and are joined at render time, so the
// generated file never duplicates catalog metadata.
//
// Run after adding components: `npm run build:component-timeline`.
// `npm run check:component-timeline` fails when this file is stale.

const catalogPath = "src/storybook/componentCatalog.ts";
const outputPath = "src/storybook/componentTimeline.ts";

// Same parsing contract as scripts/check-component-catalog.mjs: `id` is the
// first field of every entry and the string fields (`id`, `name`,
// `storyTitle`, `componentPath`) each live on a single line.
const entryPattern = /\{\s*\n\s+id: "([^"]+)",([\s\S]*?)\n  \},/g;

export function readCatalogEntries() {
  if (!existsSync(catalogPath)) {
    throw new Error(
      `missing ${catalogPath}. The component timeline derives its component list from the catalog; install/generate the catalog first.`,
    );
  }

  const source = readFileSync(catalogPath, "utf8");
  const entries = [];

  for (const match of source.matchAll(entryPattern)) {
    const id = match[1];
    const componentPath = match[2].match(/\bcomponentPath: "([^"]+)"/)?.[1];
    entries.push({ id, componentPath });
  }

  if (entries.length === 0) {
    throw new Error(
      `no entries could be parsed from ${catalogPath}. Parsing contract: \`id\` is the FIRST field of every entry and the string fields (\`id\`, \`name\`, \`storyTitle\`, \`componentPath\`) each occupy a single line.`,
    );
  }

  return entries;
}

function firstCommitFor(componentPath) {
  const raw = execFileSync(
    "git",
    [
      "log",
      "--diff-filter=A",
      "--format=%ad%x09%h%x09%s",
      "--date=short",
      "--reverse",
      "--",
      componentPath,
    ],
    { encoding: "utf8" },
  ).trim();

  if (!raw) {
    return null;
  }

  const [firstSeen, commit, ...subjectParts] = raw.split("\n")[0].split("\t");

  return { firstSeen, commit, subject: subjectParts.join("\t") };
}

export function collectComponentTimeline() {
  const catalogEntries = readCatalogEntries();

  const entries = [];
  const untracked = [];

  for (const { id, componentPath } of catalogEntries) {
    const record = componentPath ? firstCommitFor(componentPath) : null;

    if (!record) {
      untracked.push(id);
      continue;
    }

    entries.push({ id, ...record });
  }

  // Newest first, then alphabetical inside a date so page order is stable.
  entries.sort((a, b) =>
    a.firstSeen === b.firstSeen
      ? a.id.localeCompare(b.id)
      : b.firstSeen.localeCompare(a.firstSeen),
  );

  return { entries, untracked };
}

export function renderComponentTimelineModule({ entries, untracked }) {
  const rows = entries
    .map(
      (entry) =>
        `  {\n    id: ${JSON.stringify(entry.id)},\n    firstSeen: ${JSON.stringify(entry.firstSeen)},\n    commit: ${JSON.stringify(entry.commit)},\n    subject: ${JSON.stringify(entry.subject)},\n  },`,
    )
    .join("\n");

  const untrackedNote = untracked.length
    ? `\n// Not yet committed, so they have no creation date: ${untracked.join(", ")}.`
    : "";

  return `/**
 * GENERATED by scripts/component-timeline/build-component-timeline.mjs — do not edit by hand.
 * Regenerate with \`npm run build:component-timeline\`;
 * \`npm run check:component-timeline\` fails when it drifts from git history.
 *
 * Only git-derived facts live here. Name, category and storyTitle stay owned
 * by componentCatalog.ts and are joined at render time.${untrackedNote}
 */

export type ComponentTimelineEntry = {
  /** Matches a componentCatalog id; git facts derive from that entry's componentPath. */
  id: string;
  /** ISO date of the commit that first added the entry's componentPath. */
  firstSeen: string;
  commit: string;
  subject: string;
};

/** Newest first; alphabetical within a date. */
export const componentTimelineEntries: readonly ComponentTimelineEntry[] = [
${rows}
];
`;
}

function main() {
  let timeline;
  try {
    timeline = collectComponentTimeline();
  } catch (error) {
    console.error(`Component timeline build failed: ${error.message}`);
    process.exit(1);
  }

  writeFileSync(outputPath, renderComponentTimelineModule(timeline));

  const dates = new Set(timeline.entries.map((entry) => entry.firstSeen));
  console.log(
    `Component timeline written: ${timeline.entries.length} components across ${dates.size} dates.`,
  );

  if (timeline.untracked.length) {
    console.log(
      `Skipped (not committed yet): ${timeline.untracked.join(", ")}.`,
    );
  }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}
